  bp_tier_word:{tr:"KADEME",en:"TIER",de:"STUFE",fr:"PALIER",es:"NIVEL",pt:"NÍVEL",it:"LIVELLO",ru:"УРОВЕНЬ",ar:"مستوى",ja:"ティア",ko:"티어",zh:"等级",hi:"स्तर",id:"TINGKAT",pl:"POZIOM"},
  bp_days_left:{tr:"{n} gün kaldı",en:"{n} days left",de:"noch {n} Tage",fr:"{n} jours restants",es:"quedan {n} días",pt:"faltam {n} dias",it:"{n} giorni rimasti",ru:"осталось {n} дн.",ar:"تبقّى {n} يوم",ja:"残り{n}日",ko:"{n}일 남음",zh:"剩余{n}天",hi:"{n} दिन बाकी",id:"{n} hari lagi",pl:"zostało {n} dni"},
  bp_next_xp:{tr:"{tier}. kademeye {n} XP kaldı",en:"{n} XP to tier {tier}",de:"Noch {n} XP bis Stufe {tier}",fr:"{n} XP avant le palier {tier}",es:"{n} XP para el nivel {tier}",pt:"{n} XP para o nível {tier}",it:"{n} XP al livello {tier}",ru:"{n} XP до уровня {tier}",ar:"{n} XP للمستوى {tier}",ja:"ティア{tier}まであと{n} XP",ko:"티어 {tier}까지 {n} XP",zh:"距离第{tier}级还差{n} XP",hi:"स्तर {tier} तक {n} XP",id:"{n} XP lagi ke tingkat {tier}",pl:"{n} XP do poziomu {tier}"},
  bp_all_done:{tr:"Tüm kademeler açıldı!",en:"All tiers unlocked!",de:"Alle Stufen freigeschaltet!",fr:"Tous les paliers débloqués !",es:"¡Todos los niveles desbloqueados!",pt:"Todos os níveis liberados!",it:"Tutti i livelli sbloccati!",ru:"Все уровни открыты!",ar:"تم فتح كل المستويات!",ja:"全ティア解放！",ko:"모든 티어 해제!",zh:"所有等级已解锁！",hi:"सभी स्तर खुल गए!",id:"Semua tingkat terbuka!",pl:"Wszystkie poziomy odblokowane!"},
  bp_claim:{tr:"AL",en:"CLAIM",de:"HOLEN",fr:"PRENDRE",es:"RECLAMAR",pt:"PEGAR",it:"RITIRA",ru:"ВЗЯТЬ",ar:"استلم",ja:"受取",ko:"받기",zh:"领取",hi:"लें",id:"KLAIM",pl:"ODBIERZ"},
  bp_how:{tr:"Her oyunda skorunun 40'ta biri kadar sezon XP'si kazanırsın. Sezon bitince kademeler sıfırlanır.",en:"Each run gives season XP equal to 1/40 of your score. Tiers reset when the season ends.",de:"Jede Runde bringt Saison-XP in Höhe von 1/40 deiner Punkte. Am Saisonende werden die Stufen zurückgesetzt.",fr:"Chaque partie rapporte de l'XP de saison égale à 1/40 de ton score. Les paliers repartent à zéro en fin de saison.",es:"Cada partida da XP de temporada igual a 1/40 de tu puntuación. Los niveles se reinician al acabar la temporada.",pt:"Cada partida dá XP de temporada igual a 1/40 da sua pontuação. Os níveis zeram no fim da temporada.",it:"Ogni partita dà XP stagionali pari a 1/40 del punteggio. I livelli si azzerano a fine stagione.",ru:"Каждая игра даёт сезонный опыт, равный 1/40 очков. В конце сезона уровни сбрасываются.",ar:"كل جولة تمنحك XP موسميًا يساوي 1/40 من نقاطك. تُعاد المستويات عند نهاية الموسم.",ja:"毎回スコアの1/40がシーズンXPになります。シーズン終了でティアはリセット。",ko:"매 판 점수의 1/40만큼 시즌 XP를 얻어요. 시즌이 끝나면 티어가 초기화돼요.",zh:"每局获得分数1/40的赛季经验。赛季结束时等级重置。",hi:"हर गेम में आपके स्कोर का 1/40 सीज़न XP मिलता है। सीज़न ख़त्म होने पर स्तर रीसेट होते हैं।",id:"Setiap permainan memberi XP musim sebesar 1/40 skor. Tingkat direset saat musim berakhir.",pl:"Każda gra daje XP sezonu równe 1/40 wyniku. Poziomy zerują się po sezonie."},
  ach_virtuoso_name:{tr:"Virtüöz",en:"Virtuoso",de:"Virtuose",fr:"Virtuose",es:"Virtuoso",pt:"Virtuoso",it:"Virtuoso",ru:"Виртуоз",ar:"البارع",ja:"ヴィルトゥオーゾ",ko:"거장",zh:"演奏大师",hi:"उस्ताद",id:"Virtuoso",pl:"Wirtuoz"},
  ach_virtuoso_desc:{tr:"Tek oyunda 4000 puan yap",en:"Score 4000 in a single run",de:"Erziele 4000 Punkte in einer Runde",fr:"Marque 4000 points en une partie",es:"Consigue 4000 puntos en una partida",pt:"Faça 4000 pontos numa partida",it:"Fai 4000 punti in una partita",ru:"Набери 4000 очков за одну игру",ar:"احصل على 4000 نقطة في جولة واحدة",ja:"1回で4000点を取る",ko:"한 판에 4000점 달성",zh:"单局得分4000",hi:"एक गेम में 4000 अंक बनाओ",id:"Raih 4000 poin dalam satu permainan",pl:"Zdobądź 4000 pkt w jednej grze"},
  ach_bossslayer_name:{tr:"Boss Avcısı",en:"Boss Slayer",de:"Bossbezwinger",fr:"Tueur de boss",es:"Cazajefes",pt:"Caçador de chefes",it:"Ammazzaboss",ru:"Убийца боссов",ar:"صائد الزعماء",ja:"ボスハンター",ko:"보스 사냥꾼",zh:"首领猎手",hi:"बॉस शिकारी",id:"Pemburu Bos",pl:"Pogromca bossów"},
  ach_bossslayer_desc:{tr:"Tek oyunda 3 boss dalgasını temizle",en:"Clear 3 boss waves in a single run",de:"Besiege 3 Boss-Wellen in einer Runde",fr:"Termine 3 vagues de boss en une partie",es:"Supera 3 oleadas de jefe en una partida",pt:"Supere 3 ondas de chefe numa partida",it:"Supera 3 ondate boss in una partita",ru:"Пройди 3 волны боссов за одну игру",ar:"اجتز 3 موجات زعماء في جولة واحدة",ja:"1回でボスウェーブを3回クリア",ko:"한 판에 보스 웨이브 3번 클리어",zh:"单局清除3波首领",hi:"एक गेम में 3 बॉस वेव पार करो",id:"Bersihkan 3 gelombang bos dalam satu permainan",pl:"Pokonaj 3 fale bossów w jednej grze"},
  ach_untouchable_name:{tr:"Dokunulmaz",en:"Untouchable",de:"Unantastbar",fr:"Intouchable",es:"Intocable",pt:"Intocável",it:"Intoccabile",ru:"Неприкасаемый",ar:"لا يُمَس",ja:"無傷の達人",ko:"무적",zh:"毫发无伤",hi:"अछूता",id:"Tak Tersentuh",pl:"Nietykalny"},
  ach_untouchable_desc:{tr:"Hiç hasar almadan tek oyunda 1000 puan yap",en:"Score 1000 in a run without taking a hit",de:"Erziele 1000 Punkte ohne Treffer",fr:"Marque 1000 points sans être touché",es:"Consigue 1000 puntos sin recibir daño",pt:"Faça 1000 pontos sem levar dano",it:"Fai 1000 punti senza subire colpi",ru:"Набери 1000 очков без единого удара",ar:"احصل على 1000 نقطة دون أي ضربة",ja:"ノーダメージで1000点を取る",ko:"한 번도 맞지 않고 1000점 달성",zh:"零受伤单局得分1000",hi:"बिना चोट खाए 1000 अंक बनाओ",id:"Raih 1000 poin tanpa terkena serangan",pl:"Zdobądź 1000 pkt bez trafienia"},
