  duel_opp_ko_flash:{tr:"RAKİP ELENDİ!",en:"OPPONENT KNOCKED OUT!",de:"GEGNER K.O.!",fr:"ADVERSAIRE K.O. !",es:"¡RIVAL ELIMINADO!",pt:"RIVAL ELIMINADO!",it:"AVVERSARIO K.O.!",ru:"СОПЕРНИК ВЫБЫЛ!",ar:"تم إقصاء الخصم!",ja:"相手ノックアウト!",ko:"상대 탈락!",zh:"对手出局！",hi:"प्रतिद्वंद्वी बाहर!",id:"LAWAN TUMBANG!",pl:"RYWAL ZNOKAUTOWANY!"},
  duel_why_oppko:{tr:"Rakibin canı bitti ve elendi — kazandın!",en:"Your opponent ran out of HP and was knocked out — you win!",de:"Dein Gegner hatte keine Leben mehr — du gewinnst!",fr:"L'adversaire n'a plus de PV, il est éliminé — tu gagnes !",es:"Tu rival se quedó sin vida y quedó eliminado: ¡ganas!",pt:"O rival ficou sem vidas e foi eliminado — você venceu!",it:"L'avversario ha finito le vite ed è fuori — hai vinto!",ru:"У соперника кончились жизни — ты победил!",ar:"نفدت حياة خصمك وأُقصي — فزت!",ja:"相手のHPが尽きてノックアウト — 勝利!",ko:"상대 HP가 바닥나 탈락 — 승리!",zh:"对手生命耗尽出局——你赢了！",hi:"प्रतिद्वंद्वी का HP खत्म, वह बाहर — तुम जीते!",id:"Nyawa lawan habis dan tumbang — kamu menang!",pl:"Rywalowi skończyło się życie — wygrywasz!"},
  duel_why_ko:{tr:"Canın bitti ve elendin",en:"You ran out of HP and were knocked out",de:"Du hattest keine Leben mehr",fr:"Tu n'as plus de PV, tu es éliminé",es:"Te quedaste sin vida y quedaste eliminado",pt:"Suas vidas acabaram e você foi eliminado",it:"Hai finito le vite e sei fuori",ru:"У тебя кончились жизни",ar:"نفدت حياتك وأُقصيت",ja:"HPが尽きてノックアウト",ko:"HP가 바닥나 탈락했어요",zh:"你生命耗尽出局",hi:"तुम्हारा HP खत्म, तुम बाहर",id:"Nyawamu habis, kamu tumbang",pl:"Skończyło ci się życie"},
  duel_why_kohi:{tr:"Puanın daha yüksekti ama canın önce bitti — elenen kaybeder",en:"Your score was higher, but you ran out of HP first — a knockout loses",de:"Deine Punkte waren höher, aber deine Leben waren zuerst weg — K.o. verliert",fr:"Ton score était plus haut, mais tes PV sont tombés à zéro d'abord — le K.O. perd",es:"Tenías más puntos, pero te quedaste sin vida primero: quien cae pierde",pt:"Sua pontuação era maior, mas suas vidas acabaram antes — quem cai perde",it:"Avevi più punti, ma hai finito le vite prima — chi va K.O. perde",ru:"Очков было больше, но жизни кончились раньше — выбывший проигрывает",ar:"نتيجتك كانت أعلى لكن حياتك نفدت أولًا — من يُقصى يخسر",ja:"スコアは上だったが先にHPが尽きた — ノックアウトは負け",ko:"점수는 높았지만 HP가 먼저 바닥났어요 — 탈락하면 패배",zh:"你分数更高，但生命先耗尽——出局即判负",hi:"स्कोर ज़्यादा था, पर HP पहले खत्म — बाहर होने वाला हारता है",id:"Skormu lebih tinggi, tapi nyawamu habis duluan — yang tumbang kalah",pl:"Miałeś więcej punktów, ale pierwszy straciłeś życie — nokaut przegrywa"},
  duel_why_timew:{tr:"Süre bitti — puanın daha yüksek",en:"Time's up — your score is higher",de:"Zeit um — deine Punktzahl ist höher",fr:"Temps écoulé — ton score est plus haut",es:"Se acabó el tiempo: tienes más puntos",pt:"Tempo esgotado — sua pontuação é maior",it:"Tempo scaduto — hai più punti",ru:"Время вышло — у тебя больше очков",ar:"انتهى الوقت — نتيجتك أعلى",ja:"タイムアップ — スコアで上回った",ko:"시간 종료 — 점수가 더 높아요",zh:"时间到——你分数更高",hi:"समय खत्म — तुम्हारा स्कोर ज़्यादा",id:"Waktu habis — skormu lebih tinggi",pl:"Koniec czasu — masz więcej punktów"},
  duel_why_timel:{tr:"Süre bitti — rakibin puanı daha yüksek",en:"Time's up — your opponent scored higher",de:"Zeit um — der Gegner hat mehr Punkte",fr:"Temps écoulé — l'adversaire a plus de points",es:"Se acabó el tiempo: tu rival tiene más puntos",pt:"Tempo esgotado — o rival fez mais pontos",it:"Tempo scaduto — l'avversario ha più punti",ru:"Время вышло — у соперника больше очков",ar:"انتهى الوقت — نتيجة خصمك أعلى",ja:"タイムアップ — 相手のスコアが上",ko:"시간 종료 — 상대 점수가 더 높아요",zh:"时间到——对手分数更高",hi:"समय खत्म — प्रतिद्वंद्वी का स्कोर ज़्यादा",id:"Waktu habis — skor lawan lebih tinggi",pl:"Koniec czasu — rywal ma więcej punktów"},
