  legal_title:{tr:'Gizlilik & Yasal',en:'Privacy & Legal',de:'Datenschutz & Recht',fr:'Confidentialité & mentions légales',es:'Privacidad y legal',pt:'Privacidade e legal',it:'Privacy e legale',ru:'Конфиденциальность и право',ar:'الخصوصية والقانونية',ja:'プライバシーと法的情報',ko:'개인정보 및 법적 정보',zh:'隐私与法律',hi:'गोपनीयता और कानूनी',id:'Privasi & Hukum',pl:'Prywatność i prawo'},
  kvkk_banner:{"tr": "Oyunu senin için daha iyi yapmak istiyoruz 🎧 Anonim oyun istatistiklerini kullanmamıza izin verir misin?", "en": "Help us make the game better for you 🎧 May we use anonymous gameplay stats?", "de": "Hilf uns, das Spiel für dich besser zu machen 🎧 Dürfen wir anonyme Spielstatistiken nutzen?", "fr": "Aide-nous à rendre le jeu meilleur pour toi 🎧 Pouvons-nous utiliser des statistiques de jeu anonymes ?", "es": "Ayúdanos a mejorar el juego para ti 🎧 ¿Podemos usar estadísticas de juego anónimas?", "pt": "Ajude a deixar o jogo melhor para você 🎧 Podemos usar estatísticas de jogo anônimas?", "it": "Aiutaci a rendere il gioco migliore per te 🎧 Possiamo usare statistiche di gioco anonime?", "ru": "Помоги нам сделать игру лучше 🎧 Можно использовать анонимную игровую статистику?", "ar": "ساعدنا في جعل اللعبة أفضل لك 🎧 هل نستخدم إحصاءات لعب مجهولة؟", "ja": "ゲームをもっと良くしたい！🎧 匿名のプレイ統計を使ってもいい？", "ko": "게임을 더 좋게 만들고 싶어 🎧 익명 플레이 통계를 써도 될까?", "zh": "帮我们把游戏做得更好 🎧 可以使用匿名游戏统计吗？", "hi": "गेम को तुम्हारे लिए बेहतर बनाने में मदद करो 🎧 क्या हम गुमनाम गेम आँकड़े इस्तेमाल करें?", "id": "Bantu kami membuat game lebih seru 🎧 Boleh kami pakai statistik permainan anonim?", "pl": "Pomóż nam ulepszyć grę 🎧 Czy możemy używać anonimowych statystyk gry?"},
  kvkk_accept:{"tr": "Kabul et", "en": "Accept", "de": "Akzeptieren", "fr": "Accepter", "es": "Aceptar", "pt": "Aceitar", "it": "Accetta", "ru": "Принять", "ar": "قبول", "ja": "同意する", "ko": "동의", "zh": "同意", "hi": "स्वीकार करें", "id": "Terima", "pl": "Akceptuję"},
